pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Owned} from "../src/Owned.sol";

contract InvMutTest is Test {
    Owned c;
    function setUp() public { c = new Owned(); }
    function testFuzz_property(address sender, address newOwner) public {
        vm.assume(sender != c.owner());
        vm.prank(sender);
        bool ok;
        try c.transferOwnership(newOwner) { ok = true; } catch { ok = false; }
        assertFalse(ok);
    }
}
